#![allow(dead_code, unused)]
//! MIPI I3C SDR master on RP2350 PIO2.
//!
//! This is a Rust port of the I3CBlaster reference controller
//! (`ref/I3CBlaster/src/i3c.pio` + `ref/I3cBlaster/src/i3c_hl.c`):
//!
//!   MIT License
//!   Copyright (c) 2024 xyphro, Kai Gossner, xyphro@gmail.com
//!
//! The SDR interpreter state machine, the T-bit overlay and the exec helper
//! templates are reproduced verbatim with `pio_asm!`.  All bus timing
//! (open-drain arbitration, push-pull SDR data with per-byte T parity, ACK /
//! NACK sampling, START / RESTART / STOP) is generated by PIO2 state machine 0.
//! HDR-DDR is intentionally out of scope.
//!
//! GP10 = SDA, GP11 = SCL (confirmed hardware ordering).  PIO2 funcsel is 8.
//! A dedicated Embassy task owns PIO2 and executes commands serialized through
//! [`I3C_INSTANCE`]; the REST layer only submits commands and collects results.

use crate::pin_owner;
use embassy_rp::peripherals::PIO2;
use embassy_rp::pio::program::pio_asm;
use embassy_rp::Peri;
use embassy_sync::blocking_mutex::raw::CriticalSectionRawMutex;
use embassy_sync::mutex::Mutex;
use embassy_sync::signal::Signal;
use rp_pac as pac;

/// I3C SDA/SCL share the adapter pair. Bench hardware-confirmed order: GP11=SDA, GP10=SCL.
pub const I3C_PINS: [u32; 2] = [11, 10];
const SDA: u32 = I3C_PINS[0]; // 11
const SCL: u32 = I3C_PINS[1]; // 10
const FUNCSEL_PIO2: u8 = 8; // PIO2_0 (see servo.rs funcsel table 6/7/8=PIO0/1/2)
const FUNCSEL_SIO: u8 = 5; // bit-banged I2C fallback

// Controller status codes (mirror i3c_hl_status_t).
pub const ST_OK: i8 = 0;
pub const ST_IBI: i8 = 1;
pub const ST_NAK_ARBHDR: i8 = 2;
pub const ST_NAK_ADDR: i8 = 3;
pub const ST_PARAM: i8 = 4;

// ---------------------------------------------------------------------------
// Command / result transport between REST handlers and the PIO2 task.
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum CmdKind {
    Init,
    Transfer,     // write (tx) then read (rx), two I3C transactions
    CccBroadcast, // data[0..len] sent after the 0x7E broadcast header
    EntDaa,
    RstDaa,
    TargetReset,
    I2cPinMode, // data[0] != 0 -> SIO/I2C, else PIO2/I3C
    Poll,
    SetPins,    // data[0] = SCL, data[1] = SDA (0, 0 = swap)
    I2cScan,
}

#[derive(Clone, Copy)]
pub struct I3cCommand {
    pub kind: CmdKind,
    pub addr: u8,
    pub flags: u8,
    pub data: [u8; 128],
    pub data_len: u8,
    pub rx_len: u8,
    pub freq_khz: u32,
}

impl Default for I3cCommand {
    fn default() -> Self {
        Self { kind: CmdKind::Init, addr: 0, flags: 0, data: [0; 128], data_len: 0, rx_len: 0, freq_khz: 1000 }
    }
}

#[derive(Clone, Copy)]
pub struct I3cResult {
    pub status: i8,
    pub addr: u8,
    pub written: u8,
    pub rx: [u8; 128],
    pub rx_len: u8,
    pub diag_d0: u32,   // raw arbitration-header phase-1 read
    pub diag_d1: u32,   // raw arbitration-header phase-2 read
}

impl Default for I3cResult {
    fn default() -> Self {
        Self { status: ST_OK, addr: 0, written: 0, rx: [0; 128], rx_len: 0, diag_d0: 0, diag_d1: 0 }
    }
}

pub static I3C_CMD: Signal<CriticalSectionRawMutex, I3cCommand> = Signal::new();
static ARB_D0: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);
static ARB_D1: core::sync::atomic::AtomicU32 = core::sync::atomic::AtomicU32::new(0);
pub static I3C_RESULT: Signal<CriticalSectionRawMutex, I3cResult> = Signal::new();

pub static I3C_INSTANCE: Mutex<CriticalSectionRawMutex, I3cBridge> = Mutex::new(I3cBridge::new());

// ---------------------------------------------------------------------------
// Assembled PIO program image (built once by the task).
// ---------------------------------------------------------------------------

#[derive(Clone, Copy)]
struct Programs {
    sdr: [u16; 32],
    sdr_len: usize,
    overlay: [u16; 32],
    overlay_len: usize,
    helper: [u16; 16],
    off_stop: u32,
    off_restart: u32,
    off_scl0: u32,
    off_exec: u32,
    off_xfer: u32,
    off_overlay_restart: u32,
}

fn build_programs() -> Programs {
    // Main SDR interpreter. Instruction offsets are consumed by `out pc, 5`.
    let sdr = pio_asm!(
        ".side_set 1 opt",
        ".wrap_target",
        "inst_parser:",
        "    pull block",
        "    out pc, 5",
        "PUBLIC cmd_stop:",
        "    out y, 10    side 0",
        "    set pins, 0",
        "    set pindirs, 1 [4]",
        "stop_delay:",
        "    jmp y--, stop_delay",
        "    nop side 1 [2]",
        "    set pindirs, 0",
        "    jmp inst_parser",
        "PUBLIC cmd_restart:",
        "    nop side 0 [0]",
        "    set pins, 1",
        "    set pindirs, 1 [4]",
        "    nop side 1 [4]",
        "    set pins, 0 [4]",
        "    jmp inst_parser",
        "PUBLIC cmd_scl0:",
        "    nop",
        "    jmp inst_parser side 0 [0]",
        "PUBLIC cmd_exec:",
        "    out exec, 16",
        "    jmp inst_parser",
        "    nop",
        "PUBLIC cmd_xfer_bits:",
        "    out x, 3",
        "    jmp fastentry side 0",
        "nextbit:",
        "    nop [2]",
        "fastentry:",
        "    out pindirs, 1 side 0 [0]",
        "    out pins, 1 side 0 [0]",
        "    out y, 1",
        "    jmp !y, skipdelay",
        "    set y, 1 [3]",
        "delay:",
        "    jmp y--, delay [7]",
        "skipdelay:",
        "    in pins, 1 [0]",
        "    out pindirs, 1 side 1",
        "    jmp x-- nextbit [0]",
        ".wrap",
    );

    // T-bit overlay: replaces the main restart handler at offset 9 during SDR reads.
    let overlay = pio_asm!(
        ".side_set 1 opt",
        ".wrap_target",
        "inst_parser:",
        "    nop",
        "    nop",
        "    nop",
        "    nop",
        "    nop",
        "    nop",
        "    nop",
        "    nop",
        "    nop",
        "PUBLIC cmd_restart:",
        "    nop",
        "    nop side 0 [2]",
        "    in pins, 1",
        "    jmp pin, target_wants_to_continue",
        "    out NULL, 2",
        "target_wants_to_continue:",
        "    out pindirs, 1 side 1 [1]",
        "    out pindirs, 1 [2]",
        "    nop side 0",
        "    set pindirs, 0 [4]",
        "    jmp inst_parser side 0 [1]",
        ".wrap",
    );

    // Exec templates (never loaded into PIO memory; used as `out exec` values).
    let helper = pio_asm!(
        ".side_set 1 opt",
        "    set pindirs, 1 side 1 [3]",
        "    out pindirs, 2 side 1",
        "    nop side 0",
        "    out pindirs, 1 [0]",
        "    out pins, 1 [0]",
        "    nop side 1 [0]",
        "    nop side 1 [7]",
        "    nop side 0 [7]",
        "    out x, 5",
    );

    let mut sdr_arr = [0u16; 32];
    for (i, &w) in sdr.program.code.iter().enumerate() { sdr_arr[i] = w; }
    let mut ov_arr = [0u16; 32];
    for (i, &w) in overlay.program.code.iter().enumerate() { ov_arr[i] = w; }
    let mut hp_arr = [0u16; 16];
    for (i, &w) in helper.program.code.iter().enumerate() { hp_arr[i] = w; }

    Programs {
        sdr: sdr_arr,
        sdr_len: sdr.program.code.len(),
        overlay: ov_arr,
        overlay_len: overlay.program.code.len(),
        helper: hp_arr,
        off_stop: sdr.public_defines.cmd_stop as u32,
        off_restart: sdr.public_defines.cmd_restart as u32,
        off_scl0: sdr.public_defines.cmd_scl0 as u32,
        off_exec: sdr.public_defines.cmd_exec as u32,
        off_xfer: sdr.public_defines.cmd_xfer_bits as u32,
        off_overlay_restart: overlay.public_defines.cmd_restart as u32,
    }
}

// ---------------------------------------------------------------------------
// Low-level PIO2 access (state machine 0).
// ---------------------------------------------------------------------------

#[inline(always)]
fn wait_tx_empty() {
    while pac::PIO2.fstat().read().txempty() & 1 == 0 {}
}

#[inline(always)]
fn wait_idle() {
    while pac::PIO2.sm(0).addr().read().addr() != 0 {}
}

#[inline(always)]
fn put32(word: u32) {
    while pac::PIO2.fstat().read().txfull() & 1 != 0 {}
    pac::PIO2.txf(0).write_value(word);
}

#[inline(always)]
fn put32_no_check(word: u32) {
    pac::PIO2.txf(0).write_value(word);
}

#[inline(always)]
fn get32() -> u32 {
    while pac::PIO2.fstat().read().rxempty() & 1 != 0 {}
    pac::PIO2.rxf(0).read()
}

#[inline(always)]
fn set_autopush(bits: u8) {
    pac::PIO2.sm(0).shiftctrl().write(|w| {
        w.set_pull_thresh(0);
        w.set_out_shiftdir(true); // shift right (LSB out first)
        w.set_in_shiftdir(false);
        w.set_push_thresh(bits);
        w.set_autopush(true);
        w.set_autopull(false);
    });
}

fn set_clkdiv(freq_khz: u32) -> bool {
    if freq_khz < 40 || freq_khz > 12_500 {
        return false;
    }
    // PIO clock is 10x the requested SCL rate: the interpreter uses 10 PIO
    // cycles per SCL period. Reference: clkdiv = 12500*65536/target_khz on a
    // 125 MHz RP2040; generalize to the actual RP2350 sys clock.
    let sys = crate::benchmark::get_sys_clk_hz() as u64;
    let pio_clk = (freq_khz as u64) * 10_000;
    let div_x256 = ((sys * 256) / pio_clk).max(256);
    let int = (div_x256 / 256) as u16;
    let frac = (div_x256 % 256) as u8;
    pac::PIO2.sm(0).clkdiv().write(|w| { w.set_int(int); w.set_frac(frac); });
    true
}

fn configure_pins(i3c_mode: bool, scl: u32, sda: u32) {
    for &pin in &[scl, sda] {
        pac::IO_BANK0.gpio(pin as usize).ctrl().write(|w| {
            w.set_funcsel(if i3c_mode { FUNCSEL_PIO2 } else { FUNCSEL_SIO });
        });
        pac::PADS_BANK0.gpio(pin as usize).modify(|w| {
            w.set_iso(false);
            w.set_ie(true);
            w.set_od(false); // PIO pindirs implements open-drain phases
            w.set_pue(true);
            w.set_pde(false);
            w.set_slewfast(true);
            w.set_drive(pac::pads::vals::Drive::_12M_A);
        });
    }
}

fn pinctrl_initial(scl: u32, sda: u32) {
    let base = scl.min(sda);
    pac::PIO2.sm(0).pinctrl().write(|w| {
        w.set_set_count(1);
        w.set_set_base(scl as u8);
        w.set_out_count(2); // initial SETDIR controls both SCL and SDA (GP10 and GP11)
        w.set_out_base(base as u8);
        w.set_in_base(sda as u8);
        // Program uses `.side_set 1 opt`: 1 side bit + 1 optional-delay bit.
        // PINCTRL must reserve 2 sideset bits to match the instruction encoding;
        // count=1 desynchronises all delayed instructions (the reference uses 2).
        w.set_sideset_count(2);
        w.set_sideset_base(scl as u8);
    });
}

fn pinctrl_normal(scl: u32, sda: u32) {
    pac::PIO2.sm(0).pinctrl().write(|w| {
        w.set_set_count(1);
        w.set_set_base(sda as u8);
        w.set_out_count(1);
        w.set_out_base(sda as u8);
        w.set_in_base(sda as u8);
        w.set_sideset_count(2); // `.side_set 1 opt` needs 2 bits (side + opt-delay)
        w.set_sideset_base(scl as u8);
    });
}

fn init_pio(p: &Programs, scl: u32, sda: u32) {
    pac::PIO2.ctrl().modify(|w| w.set_sm_enable(0));

    for i in 0..p.sdr_len {
        pac::PIO2.instr_mem(i).write(|w| w.set_instr_mem(p.sdr[i]));
    }

    pac::PIO2.sm(0).execctrl().write(|w| {
        w.set_wrap_top((p.sdr_len - 1) as u8);
        w.set_wrap_bottom(0);
        w.set_side_en(true);
        w.set_jmp_pin(sda as u8);
    });
    set_autopush(0);
    pinctrl_initial(scl, sda);
    configure_pins(true, scl, sda);
    pac::PIO2.input_sync_bypass().write_value((1u32 << sda) | (1u32 << scl));
    set_clkdiv(1000);

    pac::PIO2.ctrl().modify(|w| w.set_sm_enable(1));

    // Release SDA, drive SCL (open-drain idle), then narrow OUT to SDA only.
    let (dirs0, dirs1) = if scl < sda { (1, 0) } else { (0, 1) };
    put32(opcode_setdir(dirs0, dirs1, p));
    wait_tx_empty();
    wait_idle();
    pinctrl_normal(scl, sda);
}

// ---------------------------------------------------------------------------
// Opcode helpers (mirror i3c.pio % c-sdk macros).
// ---------------------------------------------------------------------------

#[inline(always)]
fn opcode_xfer(bitcount: u32, v: [u32; 6], p: &Programs) -> u32 {
    p.off_xfer
        | ((bitcount - 1) << 5)
        | (v[0] << 8) | (v[1] << 12) | (v[2] << 16)
        | (v[3] << 20) | (v[4] << 24) | (v[5] << 28)
}

#[inline(always)]
fn opcode_exec(instr: u16, p: &Programs) -> u32 {
    ((instr as u32) << 5) | p.off_exec
}

#[inline(always)]
fn opcode_sdadir(dir: u32, p: &Programs) -> u32 {
    (dir << 21) | ((p.helper[3] as u32) << 5) | p.off_exec
}

#[inline(always)]
fn opcode_sdastate(state: u32, p: &Programs) -> u32 {
    (state << 21) | ((p.helper[4] as u32) << 5) | p.off_exec
}

#[inline(always)]
fn opcode_setdir(dirscl: u32, dirsda: u32, p: &Programs) -> u32 {
    ((p.helper[1] as u32) << 5) | (dirscl << 21) | (dirsda << 22) | p.off_exec
}

#[inline(always)]
fn opcode_start(p: &Programs) -> u32 { ((p.helper[0] as u32) << 5) | p.off_exec }
#[inline(always)]
fn opcode_stop(p: &Programs) -> u32 { p.off_stop }
#[inline(always)]
fn opcode_restart(p: &Programs) -> u32 { p.off_restart }
#[inline(always)]
fn opcode_scl0(p: &Programs) -> u32 { p.off_scl0 }
#[inline(always)]
fn opcode_scl1(p: &Programs) -> u32 { ((p.helper[5] as u32) << 5) | p.off_exec }
#[inline(always)]
fn opcode_t_bit(controller_abort: bool, p: &Programs) -> u32 {
    (1 << 8) | (1 << 7) | ((controller_abort as u32) << 6) | p.off_overlay_restart
}

// 4-bit per-bit templates. Consumption order (OUT_SHIFTDIR=right):
//   b0 -> pindirs(falling), b1 -> pins(falling), b2 -> OD delay, b3 -> pindirs(rising)
#[inline(always)] fn sdr_wbit(v: u32) -> u32 { (v << 1) | 1 | (1 << 3) }
#[inline(always)] fn od_wbit(v: u32) -> u32 { ((v ^ 1) << 0) | ((v ^ 1) << 3) | (1 << 2) }
#[inline(always)] const fn od_rbit() -> u32 { 1 << 2 }
#[inline(always)] const fn od_rackbit() -> u32 { 1 << 2 }
#[inline(always)] fn sdr_rbit(end: u32) -> u32 { end << 3 }

// ---------------------------------------------------------------------------
// I3C HAL primitives.
// ---------------------------------------------------------------------------

struct Hal<'a> { p: &'a Programs }

impl<'a> Hal<'a> {
    #[inline(always)]
    fn start(&self) { put32(opcode_start(self.p)); }
    #[inline(always)]
    fn restart(&self) { put32(opcode_restart(self.p)); put32(opcode_scl0(self.p)); }
    #[inline(always)]
    fn stop(&self) { put32(opcode_stop(self.p)); }
    #[inline(always)]
    fn scl0(&self) { put32(opcode_scl0(self.p)); }

    fn overlay(&self, on: bool) {
        wait_tx_empty();
        wait_idle();
        if on {
            let start = self.p.off_overlay_restart as usize;
            for i in start..self.p.overlay_len {
                pac::PIO2.instr_mem(i).write(|w| w.set_instr_mem(self.p.overlay[i]));
            }
        } else {
            let start = self.p.off_overlay_restart as usize;
            for i in start..self.p.overlay_len {
                pac::PIO2.instr_mem(i).write(|w| w.set_instr_mem(self.p.sdr[i]));
            }
        }
    }

    /// Address byte (7-bit address + R/W) followed by an open-drain ACK slot.
    fn sdr_write_addr(&self, value: u8) -> i8 {
        wait_tx_empty();
        set_autopush(9);
        let v = value as u32;
        let c0 = opcode_xfer(6, [
            sdr_wbit((v >> 7) & 1), sdr_wbit((v >> 6) & 1), sdr_wbit((v >> 5) & 1),
            sdr_wbit((v >> 4) & 1), sdr_wbit((v >> 3) & 1), sdr_wbit((v >> 2) & 1),
        ], self.p);
        let c1 = opcode_xfer(3, [
            sdr_wbit((v >> 1) & 1), sdr_wbit(v & 1), od_rackbit(), 0, 0, 0,
        ], self.p);
        put32_no_check(c0);
        put32_no_check(c1);
        put32_no_check(opcode_scl0(self.p));
        let resp = get32();
        if resp & 1 != 0 { ST_NAK_ADDR } else { ST_OK }
    }

    /// Push-pull SDR data byte with trailing T parity bit.
    fn sdr_write(&self, value: u8) {
        wait_tx_empty();
        set_autopush(9);
        let v = value as u32;
        let tbit = ((v.count_ones() & 1) ^ 1) as u32;
        let c0 = opcode_xfer(6, [
            sdr_wbit((v >> 7) & 1), sdr_wbit((v >> 6) & 1), sdr_wbit((v >> 5) & 1),
            sdr_wbit((v >> 4) & 1), sdr_wbit((v >> 3) & 1), sdr_wbit((v >> 2) & 1),
        ], self.p);
        let c1 = opcode_xfer(3, [
            sdr_wbit((v >> 1) & 1), sdr_wbit(v & 1), sdr_wbit(tbit), 0, 0, 0,
        ], self.p);
        put32_no_check(c0);
        put32_no_check(c1);
        put32_no_check(opcode_scl0(self.p));
        let _ = get32();
    }

    /// SDR read of one byte; returns (byte<<1 | target_end_bit).
    fn sdr_read(&self, continue_transfer: bool) -> u32 {
        wait_tx_empty();
        set_autopush(9);
        let c0 = opcode_xfer(6, [sdr_rbit(0), sdr_rbit(0), sdr_rbit(0), sdr_rbit(0), sdr_rbit(0), sdr_rbit(0)], self.p);
        let c1 = opcode_xfer(2, [sdr_rbit(0), sdr_rbit(0), 0, 0, 0, 0], self.p);
        put32_no_check(c0);
        put32_no_check(c1);
        put32_no_check(opcode_t_bit(continue_transfer, self.p));
        get32()
    }

    /// Open-drain byte write (used for the arbitration header).
    fn od_write(&self, value: u8) {
        wait_tx_empty();
        set_autopush(9);
        let v = value as u32;
        let c0 = opcode_xfer(6, [
            od_wbit((v >> 7) & 1), od_wbit((v >> 6) & 1), od_wbit((v >> 5) & 1),
            od_wbit((v >> 4) & 1), od_wbit((v >> 3) & 1), od_wbit((v >> 2) & 1),
        ], self.p);
        let c1 = opcode_xfer(3, [
            od_wbit((v >> 1) & 1), od_wbit(v & 1), od_rackbit(), 0, 0, 0,
        ], self.p);
        put32_no_check(c0);
        put32_no_check(c1);
        put32_no_check(opcode_scl0(self.p));
        let _ = get32();
    }

    /// Open-drain 8-bit read (used for the 48-bit provisional ID).
    fn od_read8(&self) -> u8 {
        wait_tx_empty();
        set_autopush(8);
        let c0 = opcode_xfer(6, [od_rbit(), od_rbit(), od_rbit(), od_rbit(), od_rbit(), od_rbit()], self.p);
        let c1 = opcode_xfer(2, [od_rbit(), od_rbit(), 0, 0, 0, 0], self.p);
        put32_no_check(c0);
        put32_no_check(c1);
        put32_no_check(opcode_scl0(self.p));
        get32() as u8
    }

    /// Arbitration header (0x7E + R/W). Returns status and sensed arbdata.
    fn arbhdr(&self) -> (i8, u8) {
        wait_tx_empty();
        set_autopush(6);
        let c0 = opcode_xfer(6, [od_wbit(1), od_wbit(1), od_wbit(1), od_wbit(1), od_wbit(1), od_wbit(1)], self.p);
        let c1 = opcode_xfer(3, [od_wbit(0), od_wbit(0), od_rackbit(), 0, 0, 0], self.p);
        let c2 = opcode_xfer(3, [od_wbit(1), od_wbit(1), od_wbit(0), 0, 0, 0], self.p);
        put32_no_check(c0);
        put32_no_check(opcode_scl0(self.p));
        let d0 = get32();
        ARB_D0.store(d0, core::sync::atomic::Ordering::Relaxed);
        set_autopush(3);
        let (st, d1) = if d0 == 0x3f {
            put32_no_check(c1);
            put32_no_check(opcode_scl0(self.p));
            let d = get32();
            // Target ACK (bit=0) is ST_OK; NACK (bit=1) is ST_NAK_ARBHDR (no targets on bus).
            (if d & 1 != 0 { ST_NAK_ARBHDR } else { ST_OK }, d)
        } else {
            put32_no_check(c2);
            put32_no_check(opcode_scl0(self.p));
            (ST_IBI, get32())
        };
        let arbdata = ((d0 << 2) | (d1 >> 1)) as u8;
        ARB_D1.store(d1, core::sync::atomic::Ordering::Relaxed);
        (st, arbdata)
    }

    /// I3C target reset pattern (9 pulses with SCL low).
    fn target_reset(&self) {
        wait_tx_empty();
        put32_no_check(opcode_scl0(self.p));
        put32_no_check(opcode_sdastate(1, self.p));
        put32_no_check(opcode_sdadir(1, self.p));
        for _ in 0..7 {
            put32(opcode_sdastate(0, self.p));
            put32(opcode_sdastate(1, self.p));
        }
        put32(opcode_scl1(self.p));
        put32(opcode_sdastate(0, self.p));
        put32(opcode_sdastate(1, self.p));
        put32(opcode_sdadir(0, self.p));
    }
}

// ---------------------------------------------------------------------------
// High-level command execution (runs only inside the PIO2 task).
// ---------------------------------------------------------------------------

fn do_write(h: &Hal, addr: u8, data: &[u8]) -> i8 {
    h.start();
    let (st, _) = h.arbhdr();
    let mut result = st;
    if st == ST_OK {
        h.restart();
        result = h.sdr_write_addr(addr << 1);
        if result == ST_OK {
            for &b in data { h.sdr_write(b); }
        }
    } else {
        // Fallback: If 0x7E arbhdr is NAKed (e.g. target already has dynamic address and does not listen to 0x7E),
        // try Direct Start directly to target dynamic address:
        h.restart();
        result = h.sdr_write_addr(addr << 1);
        if result == ST_OK {
            for &b in data { h.sdr_write(b); }
        }
    }
    h.stop();
    result
}

fn do_read(h: &Hal, addr: u8, rx: &mut [u8]) -> (i8, usize) {
    h.start();
    let _ = h.arbhdr();
    h.restart();
    let addr_st = h.sdr_write_addr((addr << 1) | 1);
    let mut n = 0usize;
    if addr_st == ST_OK {
        h.overlay(true);
        for i in 0..rx.len() {
            let v = h.sdr_read(i + 1 == rx.len());
            rx[i] = (v >> 1) as u8;
            n += 1;
        }
        h.overlay(false);
    }
    h.stop();
    (if addr_st == ST_OK { ST_OK } else { addr_st }, n)
}

fn do_ccc_broadcast(h: &Hal, data: &[u8]) -> i8 {
    h.start();
    let (st, _) = h.arbhdr();
    if st == ST_OK {
        for &b in data { h.sdr_write(b); }
    }
    h.stop();
    st
}

/// Dynamic address assignment (ENTDAA), following `i3c_hl_entdaa()`.
///
/// Returns `(status, assigned_address)`.  The first tuple element is a status
/// code, never an address; the second is the assigned address on success.
/// `pid` receives the 6-byte provisioned ID followed by BCR and DCR.
fn do_entdaa(h: &Hal, proposed: u8, pid: &mut [u8; 8]) -> (i8, u8) {
    h.start();
    let (st, _) = h.arbhdr();
    if st != ST_OK {
        h.stop();
        return (st, 0);
    }
    h.sdr_write(0x07); // ENTDAA broadcast CCC
    h.restart();
    // 0x7E read: every unassigned target drives its 48-bit PID + BCR + DCR;
    // the lowest value wins arbitration.
    let a_st = h.sdr_write_addr((0x7e << 1) | 1);
    if a_st != ST_OK {
        h.stop();
        return (a_st, 0);
    }
    for b in pid.iter_mut() { *b = h.od_read8(); }
    // 7-bit address + R/W=0 (shifted) followed by odd parity (PAR). The
    // winning target ACKs only when PAR is valid; defer to its ACK slot.
    let shifted = (proposed as u32) << 1;
    let par = (shifted.count_ones() & 1) ^ 1;
    let w_st = h.sdr_write_addr((shifted | par) as u8);
    h.stop();
    if w_st == ST_OK { (ST_OK, proposed) } else { (w_st, 0) }
}

fn do_rstdaa(h: &Hal) -> i8 {
    h.start();
    let (st, _) = h.arbhdr();
    if st == ST_OK { h.sdr_write(0x06); }
    h.stop();
    st
}

fn restore_pio_after_i2c(p: &Programs, scl: u32, sda: u32) {
    configure_pins(true, scl, sda);
    pinctrl_initial(scl, sda);
    pac::PIO2.ctrl().modify(|w| w.set_sm_enable(1));
    let (dirs0, dirs1) = if scl < sda { (1, 0) } else { (0, 1) };
    put32(opcode_setdir(dirs0, dirs1, p));
    wait_tx_empty();
    wait_idle();
    pinctrl_normal(scl, sda);
}

fn ensure_pio_pins_ready(p: &Programs, scl: u32, sda: u32) {
    let scl_ok = pac::IO_BANK0.gpio(scl as usize).ctrl().read().funcsel() == FUNCSEL_PIO2;
    let sda_ok = pac::IO_BANK0.gpio(sda as usize).ctrl().read().funcsel() == FUNCSEL_PIO2;
    let sm_ok = (pac::PIO2.ctrl().read().sm_enable() & 1) != 0;
    if !scl_ok || !sda_ok || !sm_ok {
        restore_pio_after_i2c(p, scl, sda);
    }
}

fn execute(cmd: I3cCommand, p: &Programs) -> I3cResult {
    let h = Hal { p };
    let mut r = I3cResult::default();
    let (scl, sda) = crate::bridge::bus_pins();
    match cmd.kind {
        CmdKind::Init => {
            ensure_pio_pins_ready(p, scl as u32, sda as u32);
            r.status = if set_clkdiv(cmd.freq_khz) { ST_OK } else { ST_PARAM };
        }
        CmdKind::Transfer => {
            if cmd.flags & agentla_bridges::i3c_bulk::I3C_FLAG_OPEN_DRAIN != 0 {
                let len = cmd.data_len as usize;
                let rx_len = cmd.rx_len as usize;
                pac::PIO2.ctrl().modify(|w| w.set_sm_enable(0));
                let (ok, written, read) = crate::bridge::i2c::hw_i2c_transfer(
                    sda as u32,
                    scl as u32,
                    cmd.addr,
                    &cmd.data[..len],
                    &mut r.rx[..rx_len],
                );
                restore_pio_after_i2c(p, scl as u32, sda as u32);
                r.status = if ok { ST_OK } else { ST_NAK_ADDR };
                r.written = written as u8;
                r.rx_len = read as u8;
            } else {
                ensure_pio_pins_ready(p, scl as u32, sda as u32);
                let len = cmd.data_len as usize;
                if len > 0 || cmd.rx_len == 0 {
                    r.status = do_write(&h, cmd.addr, &cmd.data[..len]);
                    r.written = len as u8;
                    // Katapult targets stage a response after STOP, like the I2C path.
                    if cmd.rx_len > 0 && r.status == ST_OK {
                        cortex_m::asm::delay(150_000);
                    }
                }
                if cmd.rx_len > 0 && r.status == ST_OK {
                    let (st, n) = do_read(&h, cmd.addr, &mut r.rx[..cmd.rx_len as usize]);
                    r.status = st;
                    r.rx_len = n as u8;
                }
            }
        }
        CmdKind::CccBroadcast => {
            ensure_pio_pins_ready(p, scl as u32, sda as u32);
            let len = cmd.data_len as usize;
            r.status = do_ccc_broadcast(&h, &cmd.data[..len]);
        }
        CmdKind::EntDaa => {
            ensure_pio_pins_ready(p, scl as u32, sda as u32);
            let mut pid = [0u8; 8];
            let (st, assigned) = do_entdaa(&h, cmd.addr, &mut pid);
            r.status = st;
            r.addr = assigned;
            // Expose the captured PID/BCR/DCR for diagnosis; rx_len stays 0 so
            // normal transfers are unaffected.
            r.rx[..8].copy_from_slice(&pid);
        }
        CmdKind::RstDaa => {
            ensure_pio_pins_ready(p, scl as u32, sda as u32);
            r.status = do_rstdaa(&h);
        }
        CmdKind::TargetReset => {
            ensure_pio_pins_ready(p, scl as u32, sda as u32);
            h.target_reset();
        }
        CmdKind::I2cPinMode => {
            let i2c = cmd.data[0] != 0;
            pac::PIO2.ctrl().modify(|w| w.set_sm_enable(0));
            configure_pins(!i2c, scl as u32, sda as u32);
            if !i2c {
                pinctrl_initial(scl as u32, sda as u32);
                pac::PIO2.ctrl().modify(|w| w.set_sm_enable(1));
                let (dirs0, dirs1) = if scl < sda { (1, 0) } else { (0, 1) };
                put32(opcode_setdir(dirs0, dirs1, p));
                wait_tx_empty();
                wait_idle();
                pinctrl_normal(scl as u32, sda as u32);
            }
        }
        CmdKind::Poll => {
            ensure_pio_pins_ready(p, scl as u32, sda as u32);
            // IBI type-1 check: SDA held low by a target while idle.
            r.status = if (pac::SIO.gpio_in(0).read() & (1 << sda)) == 0 { ST_IBI } else { ST_OK };
        }
        CmdKind::SetPins => {
            let (new_scl, new_sda) = if cmd.data[0] == 0 && cmd.data[1] == 0 {
                crate::bridge::swap_bus_pins()
            } else {
                crate::bridge::set_bus_pins(cmd.data[0], cmd.data[1]);
                (cmd.data[0], cmd.data[1])
            };
            init_pio(p, new_scl as u32, new_sda as u32);
            r.status = ST_OK;
            r.rx[0] = new_scl;
            r.rx[1] = new_sda;
            r.rx_len = 2;
        }
        CmdKind::I2cScan => {
            let (scl, sda) = crate::bridge::bus_pins();
            pac::PIO2.ctrl().modify(|w| w.set_sm_enable(0));
            let found = crate::bridge::i2c::hw_i2c_scan(sda as u32, scl as u32);
            restore_pio_after_i2c(p, scl as u32, sda as u32);
            let n = found.len().min(r.rx.len());
            r.rx[..n].copy_from_slice(&found[..n]);
            r.rx_len = n as u8;
            r.status = ST_OK;
        }
    }
    r.diag_d0 = ARB_D0.load(core::sync::atomic::Ordering::Relaxed);
    r.diag_d1 = ARB_D1.load(core::sync::atomic::Ordering::Relaxed);
    r
}

/// Embassy task owning PIO2. Spawned once at boot from `main.rs`.
#[embassy_executor::task]
pub async fn i3c_task(_pio2: Peri<'static, PIO2>) {
    let programs = build_programs();
    let (scl, sda) = crate::bridge::bus_pins();
    init_pio(&programs, scl as u32, sda as u32);
    loop {
        let cmd = I3C_CMD.wait().await;
        let result = execute(cmd, &programs);
        I3C_RESULT.signal(result);
    }
}

// ---------------------------------------------------------------------------
// Public bridge API (software state; pin claims owned by bridge::i3c_enable).
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct I3cConfig { pub freq_khz: u32 }

pub struct I3cBridge {
    active: bool,
    /// True after the PIO2 funcsel/pads have been (re)applied following the
    /// single pin claim. `pin_owner::claim` quiesces pins back to SIO, so the
    /// first bus command after enable must reconfigure them.
    pins_ready: bool,
    pub config: I3cConfig,
    pub devices: heapless::Vec<u8, 16>,
    last_status: heapless::String<64>,
}

impl I3cBridge {
    pub const fn new() -> Self {
        Self {
            active: false,
            pins_ready: false,
            config: I3cConfig { freq_khz: 1000 },
            devices: heapless::Vec::new(),
            last_status: heapless::String::new(),
        }
    }

    pub fn active(&self) -> bool { self.active }
    pub fn device_count(&self) -> usize { self.devices.len() }
    pub fn status(&self) -> &str { self.last_status.as_str() }
    pub fn safe_pins() -> &'static [u32] { &I3C_PINS }

    /// Software enable only. The single GP10/11 claim is owned by
    /// `crate::bridge::i3c_enable()` (I3C_SLOT), so this must not claim pins.
    pub fn enable(&mut self) -> Result<(), pin_owner::ClaimError> {
        if !self.active {
            self.active = true;
            self.pins_ready = false; // claim quiesces pins; reconfigure before first transfer
            self.devices.clear();
            self.last_status.clear();
            let _ = self.last_status.push_str("I3C_READY");
        }
        Ok(())
    }

    pub fn disable(&mut self) {
        self.active = false;
        self.pins_ready = false;
        self.devices.clear();
        self.last_status.clear();
    }

    async fn raw_call(&mut self, cmd: I3cCommand) -> I3cResult {
        I3C_CMD.signal(cmd);
        I3C_RESULT.wait().await
    }

    async fn call(&mut self, cmd: I3cCommand) -> I3cResult {
        if !self.pins_ready {
            // Re-apply PIO2 funcsel (8), fast slew, 12 mA after the claim.
            let ready = self.raw_call(I3cCommand { kind: CmdKind::I2cPinMode, ..Default::default() }).await;
            if ready.status == ST_OK { self.pins_ready = true; }
        }
        self.raw_call(cmd).await
    }

    pub async fn init(&mut self, freq_khz: u32) -> bool {
        let freq = if freq_khz == 0 { 1000 } else { freq_khz };
        let r = self.call(I3cCommand { kind: CmdKind::Init, freq_khz: freq, ..Default::default() }).await;
        if r.status == ST_OK {
            self.config.freq_khz = freq;
            self.last_status.clear();
            let _ = self.last_status.push_str("INIT_OK");
            true
        } else {
            false
        }
    }

    pub async fn entdaa(&mut self) -> u8 {
        // Propose the target's static address (0x40) as its dynamic address so
        // the already-wired Katapult endpoint keeps working after DAA.
        self.entdaa_with_addr(0x40).await
    }

    /// Perform ENTDAA proposing `proposed` as the dynamic address. Returns the
    /// assigned address (0 on failure).
    pub async fn entdaa_with_addr(&mut self, proposed: u8) -> u8 {
        self.entdaa_diag(proposed).await.0
    }

    /// Full ENTDAA result: `(assigned_address, pid)` where `pid` is the
    /// 6-byte provisioned ID followed by BCR and DCR of the winning target.
    pub async fn entdaa_diag(&mut self, proposed: u8) -> (u8, [u8; 8]) {
        if !self.active { return (0, [0; 8]); }
        let r = self.call(I3cCommand { kind: CmdKind::EntDaa, addr: proposed, ..Default::default() }).await;
        let mut pid = [0u8; 8];
        pid.copy_from_slice(&r.rx[..8]);
        if r.status == ST_OK && r.addr != 0 {
            if !self.devices.contains(&r.addr) { let _ = self.devices.push(r.addr); }
            (r.addr, pid)
        } else {
            (0, pid)
        }
    }

    pub async fn rstdaa(&mut self) {
        if !self.active { return; }
        let _ = self.call(I3cCommand { kind: CmdKind::RstDaa, ..Default::default() }).await;
        self.devices.clear();
    }

    pub async fn target_reset(&mut self) {
        if !self.active { return; }
        let _ = self.call(I3cCommand { kind: CmdKind::TargetReset, ..Default::default() }).await;
    }

    pub async fn ccc_broadcast_write(&mut self, data: &[u8]) -> Result<(), ()> {
        if self.ccc_broadcast_write_diag(data).await.0 { Ok(()) } else { Err(()) }
    }

    /// Returns (ok, arbhdr d0, arbhdr d1) for diagnosis.
    pub async fn ccc_broadcast_write_diag(&mut self, data: &[u8]) -> (bool, u32, u32) {
        if !self.active || data.len() > 64 { return (false, 0, 0); }
        let mut cmd = I3cCommand { kind: CmdKind::CccBroadcast, ..Default::default() };
        cmd.data_len = data.len() as u8;
        cmd.data[..data.len()].copy_from_slice(data);
        let r = self.call(cmd).await;
        (r.status == ST_OK, r.diag_d0, r.diag_d1)
    }

    pub async fn write(&mut self, addr: u8, data: &[u8]) -> Result<(), ()> {
        if !self.active || data.len() > 64 { return Err(()); }
        let mut cmd = I3cCommand { kind: CmdKind::Transfer, addr, ..Default::default() };
        cmd.data_len = data.len() as u8;
        cmd.data[..data.len()].copy_from_slice(data);
        let r = self.call(cmd).await;
        if r.status == ST_OK {
            if !self.devices.contains(&addr) { let _ = self.devices.push(addr); }
            Ok(())
        } else {
            Err(())
        }
    }

    pub async fn read(&mut self, addr: u8, len: usize) -> heapless::Vec<u8, 64> {
        let mut out = heapless::Vec::new();
        if !self.active || len == 0 { return out; }
        let r = self.call(I3cCommand { kind: CmdKind::Transfer, addr, rx_len: len.min(64) as u8, ..Default::default() }).await;
        if r.status == ST_OK {
            for &b in &r.rx[..r.rx_len as usize] { let _ = out.push(b); }
        }
        out
    }

    pub async fn read_bytes(&mut self, addr: u8, dest: &mut [u8]) -> usize {
        if !self.active || dest.is_empty() { return 0; }
        let r = self.call(I3cCommand { kind: CmdKind::Transfer, addr, rx_len: dest.len().min(64) as u8, ..Default::default() }).await;
        if r.status != ST_OK { return 0; }
        let n = (r.rx_len as usize).min(dest.len());
        dest[..n].copy_from_slice(&r.rx[..n]);
        n
    }

    pub async fn transfer(&mut self, addr: u8, tx_data: &[u8], rx_data: &mut [u8]) -> Result<(usize, usize), ()> {
        if !self.active || tx_data.len() > 64 || rx_data.len() > 64 { return Err(()); }
        let mut cmd = I3cCommand { kind: CmdKind::Transfer, addr, ..Default::default() };
        cmd.data_len = tx_data.len() as u8;
        cmd.rx_len = rx_data.len() as u8;
        cmd.data[..tx_data.len()].copy_from_slice(tx_data);
        let r = self.call(cmd).await;
        if r.status != ST_OK { return Err(()); }
        if !self.devices.contains(&addr) { let _ = self.devices.push(addr); }
        let n = (r.rx_len as usize).min(rx_data.len());
        rx_data[..n].copy_from_slice(&r.rx[..n]);
        Ok((r.written as usize, n))
    }

    pub async fn poll_ibi(&mut self) -> bool {
        if !self.active { return false; }
        let r = self.call(I3cCommand { kind: CmdKind::Poll, ..Default::default() }).await;
        r.status == ST_IBI
    }
}

/// Process an incoming AgentLA Binary I3C Bulk Frame from USB Bulk OUT and write response frame to `resp_buf`.
pub async fn execute_i3c_bulk_frame(frame_bytes: &[u8], resp_buf: &mut [u8]) -> usize {
    let Some(frame) = agentla_bridges::i3c_bulk::I3cBulkFrame::parse(frame_bytes) else {
        return 0;
    };

    let mut cmd = I3cCommand::default();
    cmd.addr = frame.header.addr;
    cmd.flags = frame.header.flags;

    match frame.header.opcode {
        agentla_bridges::i3c_bulk::I3C_OP_SET_BUS_SPEED => {
            cmd.kind = CmdKind::Init;
            if frame.payload.len() >= 4 {
                let mut b = [0u8; 4];
                b.copy_from_slice(&frame.payload[..4]);
                cmd.freq_khz = u32::from_le_bytes(b);
            } else {
                cmd.freq_khz = 1000;
            }
        }
        agentla_bridges::i3c_bulk::I3C_OP_TARGET_RESET => {
            cmd.kind = CmdKind::TargetReset;
        }
        agentla_bridges::i3c_bulk::I3C_OP_RSTDAA => {
            cmd.kind = CmdKind::RstDaa;
        }
        agentla_bridges::i3c_bulk::I3C_OP_ENTDAA => {
            cmd.kind = CmdKind::EntDaa;
        }
        agentla_bridges::i3c_bulk::I3C_OP_CCC_BROADCAST => {
            cmd.kind = CmdKind::CccBroadcast;
            let len = frame.payload.len().min(cmd.data.len());
            cmd.data[..len].copy_from_slice(&frame.payload[..len]);
            cmd.data_len = len as u8;
        }
        agentla_bridges::i3c_bulk::I3C_OP_PRIVATE_WRITE => {
            cmd.kind = CmdKind::Transfer;
            let len = frame.payload.len().min(cmd.data.len());
            cmd.data[..len].copy_from_slice(&frame.payload[..len]);
            cmd.data_len = len as u8;
            cmd.rx_len = 0;
        }
        agentla_bridges::i3c_bulk::I3C_OP_PRIVATE_READ => {
            cmd.kind = CmdKind::Transfer;
            cmd.data_len = 0;
            cmd.rx_len = (frame.header.payload_len as u8).min(128);
        }
        agentla_bridges::i3c_bulk::I3C_OP_PRIVATE_WRITE_READ => {
            cmd.kind = CmdKind::Transfer;
            let len = frame.payload.len().min(cmd.data.len());
            cmd.data[..len].copy_from_slice(&frame.payload[..len]);
            cmd.data_len = len as u8;
            cmd.rx_len = if frame.header.status == 0 {
                128
            } else {
                frame.header.status.min(128)
            };
        }
        agentla_bridges::i3c_bulk::I3C_OP_SET_PINS => {
            cmd.kind = CmdKind::SetPins;
            if frame.payload.len() >= 2 {
                cmd.data[0] = frame.payload[0];
                cmd.data[1] = frame.payload[1];
            } else {
                cmd.data[0] = 0;
                cmd.data[1] = 0;
            }
        }
        agentla_bridges::i3c_bulk::I3C_OP_I2C_SCAN => {
            cmd.kind = CmdKind::I2cScan;
        }
        _ => {
            return agentla_bridges::i3c_bulk::I3cBulkFrame::make_response(
                frame.header.seq,
                frame.header.opcode,
                agentla_bridges::i3c_bulk::I3C_STATUS_INVALID_PARAM,
                frame.header.addr,
                &[],
                resp_buf,
            ).unwrap_or(0);
        }
    }

    if crate::bridge::i3c_on().is_err() {
        return agentla_bridges::i3c_bulk::I3cBulkFrame::make_response(
            frame.header.seq,
            frame.header.opcode,
            agentla_bridges::i3c_bulk::I3C_STATUS_INVALID_PARAM,
            frame.header.addr,
            &[],
            resp_buf,
        ).unwrap_or(0);
    }

    I3C_CMD.signal(cmd);
    let r = I3C_RESULT.wait().await;

    let status = match r.status {
        ST_OK => agentla_bridges::i3c_bulk::I3C_STATUS_OK,
        ST_IBI => agentla_bridges::i3c_bulk::I3C_STATUS_IBI,
        ST_NAK_ARBHDR => agentla_bridges::i3c_bulk::I3C_STATUS_NAK_ARBHDR,
        ST_NAK_ADDR => agentla_bridges::i3c_bulk::I3C_STATUS_NAK_ADDR,
        _ => agentla_bridges::i3c_bulk::I3C_STATUS_INVALID_PARAM,
    };

    let rx_len = (r.rx_len as usize).min(r.rx.len());
    let payload = &r.rx[..rx_len];

    agentla_bridges::i3c_bulk::I3cBulkFrame::make_response(
        frame.header.seq,
        frame.header.opcode,
        status,
        r.addr,
        payload,
        resp_buf,
    ).unwrap_or(0)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn default_inactive() {
        let b = I3cBridge::new();
        assert!(!b.active());
    }
    #[test]
    fn opcode_layout() {
        assert_eq!(sdr_wbit(1), 0b1011);
        assert_eq!(sdr_wbit(0), 0b1001);
        assert_eq!(od_wbit(1), 0b0100);
        assert_eq!(od_wbit(0), 0b1101);
    }
}
